#' Code generated by ChatGPT 5.5
#' 
#' Include Manually Exported Figures in Quarto or R Markdown Documents
#'
#' Select and include one or more manually exported figure files according to
#' the current output format.
#'
#' The function chooses a PDF file when rendering to LaTeX or PDF, uses the
#' format specified by `html_format` when rendering to HTML, and defaults to
#' PNG for other output formats.
#'
#' For each requested figure, the function first constructs the expected file
#' path from `folder`, `filename`, and the selected extension. If that file does
#' not exist and the selected extension is not PNG, the function attempts to
#' use a PNG version as a fallback.
#'
#' The selected figure paths are converted to paths relative to the directory
#' containing the currently rendered input document. This makes the generated
#' figure references portable across HTML and LaTeX outputs and avoids embedding
#' machine-specific absolute paths in the rendered document.
#'
#' @param filename A character vector containing figure base names, without file
#'   extensions. For example, `"sampling_distribution"` refers to files such as
#'   `sampling_distribution.pdf` or `sampling_distribution.png`.
#'
#' @param folder A character string giving the directory that contains the
#'   manually exported figures. The default is `"figures/manual_exports"`.
#'
#' @param html_format A character string giving the preferred image extension
#'   for HTML output. The default is `"png"`. Typical alternatives include
#'   `"svg"`, `"jpg"`, or `"webp"`.
#'
#' @param check_file A logical value indicating whether the function should stop
#'   with an error when a selected figure file cannot be found. The default is
#'   `TRUE`.
#'
#' @return The value returned invisibly by [knitr::include_graphics()]. During
#'   document rendering, this value is interpreted by `knitr` as one or more
#'   figures to include.
#'
#' @details
#' The output format is detected with [knitr::is_latex_output()] and
#' [knitr::is_html_output()].
#'
#' The figure-selection logic is:
#'
#' \enumerate{
#'   \item Use `"pdf"` for LaTeX or PDF output.
#'   \item Use `html_format` for HTML output.
#'   \item Use `"png"` for all other output formats.
#'   \item If the selected non-PNG file is absent, try the corresponding PNG
#'         file as a fallback.
#' }
#'
#' Relative paths are calculated from the directory containing the current
#' input document rather than from the current R working directory. This is
#' particularly useful in Quarto book projects, where source documents may be
#' stored in subdirectories while figures are stored relative to the project
#' root.
#'
#' @section Dependencies:
#' The function requires the `knitr` and `xfun` packages. The `knitr` package is
#' checked explicitly at runtime. The `xfun` package is accessed through its
#' namespace.
#'
#' @examples
#' \dontrun{
#' # Include one figure.
#' include_manual_figure("sampling_distribution")
#'
#' # Include several figures.
#' include_manual_figure(
#'   c(
#'     "sampling_distribution_n_10",
#'     "sampling_distribution_n_100"
#'   )
#' )
#'
#' # Prefer SVG output in HTML documents.
#' include_manual_figure(
#'   "sampling_distribution",
#'   html_format = "svg"
#' )
#'
#' # Use a different figure directory.
#' include_manual_figure(
#'   "sampling_distribution",
#'   folder = "figures/edited"
#' )
#'
#' # Return the constructed path even when the file is absent.
#' include_manual_figure(
#'   "draft_figure",
#'   check_file = FALSE
#' )
#' }
#'
#' @export
include_manual_figure <- function(
    filename,
    folder = "figures/manual_exports",
    html_format = "png",
    check_file = TRUE
) {
  
  ## ---------------------------------------------------------------------------
  ## 1. Check the required package
  ## ---------------------------------------------------------------------------
  
  ## This function relies on knitr to:
  ## - detect the current document output format;
  ## - identify the input document currently being rendered;
  ## - generate the final figure inclusion instruction.
  ##
  ## requireNamespace() checks package availability without attaching the
  ## package to the search path. This avoids modifying the user's R session.
  if (!requireNamespace("knitr", quietly = TRUE)) {
    stop("Missing package: knitr")
  }
  
  ## xfun::relative_path() is used later to compute relative file paths.
  ## Checking it explicitly here produces a clearer error than waiting for the
  ## namespace lookup to fail later in the function.
  if (!requireNamespace("xfun", quietly = TRUE)) {
    stop("Missing package: xfun")
  }
  
  ## ---------------------------------------------------------------------------
  ## 2. Validate the function arguments
  ## ---------------------------------------------------------------------------
  
  ## filename must contain at least one non-missing character string.
  if (!is.character(filename) || length(filename) == 0L || anyNA(filename)) {
    stop("`filename` must be a non-empty character vector without missing values.")
  }
  
  ## Empty base names would generate paths such as ".pdf" or ".png", which are
  ## almost certainly unintended.
  if (any(!nzchar(filename))) {
    stop("`filename` must not contain empty strings.")
  }
  
  ## folder must identify exactly one directory.
  if (!is.character(folder) || length(folder) != 1L || is.na(folder)) {
    stop("`folder` must be a single non-missing character string.")
  }
  
  ## html_format must contain a single extension such as "png" or "svg".
  if (
    !is.character(html_format) ||
    length(html_format) != 1L ||
    is.na(html_format) ||
    !nzchar(html_format)
  ) {
    stop("`html_format` must be a single non-empty character string.")
  }
  
  ## Accept extensions written either as "png" or ".png" by removing a possible
  ## leading period before constructing file names.
  html_format <- sub("^\\.", "", html_format)
  
  ## check_file must be a single TRUE or FALSE value.
  if (
    !is.logical(check_file) ||
    length(check_file) != 1L ||
    is.na(check_file)
  ) {
    stop("`check_file` must be either TRUE or FALSE.")
  }
  
  ## ---------------------------------------------------------------------------
  ## 3. Select the preferred image extension for the current output format
  ## ---------------------------------------------------------------------------
  
  ## PDF is the preferred format for LaTeX output because it preserves vector
  ## graphics and usually integrates cleanly into PDF documents.
  ##
  ## For HTML, the extension is controlled by html_format.
  ##
  ## PNG is used as a conservative default for other formats, because it is
  ## widely supported by document-rendering systems.
  extension <- if (knitr::is_latex_output()) {
    "pdf"
  } else if (knitr::is_html_output()) {
    html_format
  } else {
    "png"
  }
  
  ## ---------------------------------------------------------------------------
  ## 4. Resolve the selected file for every requested figure
  ## ---------------------------------------------------------------------------
  
  ## vapply() is used instead of sapply() because the expected return type is
  ## known in advance: each input figure name must produce exactly one path.
  ##
  ## character(1) enforces that each iteration returns one character string and
  ## therefore makes the function more predictable.
  image_absolute <- vapply(
    filename,
    function(x) {
      
      ## Construct the preferred figure path from:
      ## - the figure directory;
      ## - the extension-free base name;
      ## - the extension selected for the current output format.
      ##
      ## normalizePath() converts the path to an absolute normalized path.
      ## winslash = "/" ensures portable forward slashes, including on Windows.
      ## mustWork = FALSE is required because the preferred file may not exist,
      ## in which case a PNG fallback may still be available.
      path <- normalizePath(
        file.path(
          folder,
          paste0(x, ".", extension)
        ),
        winslash = "/",
        mustWork = FALSE
      )
      
      ## If the preferred format is absent, try the corresponding PNG file.
      ##
      ## This fallback is useful when:
      ## - a PDF export is unavailable for LaTeX output;
      ## - an SVG or WebP export is unavailable for HTML output;
      ## - only a raster export has been produced manually.
      ##
      ## No second lookup is needed when the preferred format is already PNG.
      if (!file.exists(path) && extension != "png") {
        path <- normalizePath(
          file.path(
            folder,
            paste0(x, ".png")
          ),
          winslash = "/",
          mustWork = FALSE
        )
      }
      
      ## When check_file is TRUE, stop immediately if neither the preferred file
      ## nor the PNG fallback exists.
      ##
      ## The absolute path is included in the error message to make the missing
      ## file easy to locate.
      if (check_file && !file.exists(path)) {
        stop("Figure not found: ", path)
      }
      
      ## Return the selected absolute path for this figure.
      path
    },
    character(1)
  )
  
  ## ---------------------------------------------------------------------------
  ## 5. Identify the directory of the current source document
  ## ---------------------------------------------------------------------------
  
  ## knitr::current_input(dir = TRUE) returns the path of the document currently
  ## being rendered, rather than the R working directory.
  ##
  ## This distinction matters in Quarto book projects because:
  ## - the working directory may be the project root;
  ## - the current chapter may be located in a subdirectory such as "book/";
  ## - generated figure references must be valid relative to the chapter file.
  input_file <- knitr::current_input(dir = TRUE)
  
  ## A missing input path generally means that the function was called outside
  ## an active knitr rendering context.
  if (is.null(input_file) || !nzchar(input_file)) {
    stop(
      "`include_manual_figure()` must be called while knitr is rendering ",
      "an input document."
    )
  }
  
  ## Normalize the current input file path, then extract its parent directory.
  ##
  ## mustWork = TRUE is appropriate here because the source document must exist
  ## if knitr is currently rendering it.
  input_dir <- dirname(
    normalizePath(
      input_file,
      winslash = "/",
      mustWork = TRUE
    )
  )
  
  ## ---------------------------------------------------------------------------
  ## 6. Convert absolute image paths to paths relative to the source document
  ## ---------------------------------------------------------------------------
  
  ## Absolute paths are reliable during local execution but should generally not
  ## be written into the final HTML or LaTeX source because they are:
  ## - specific to one computer;
  ## - difficult to move between systems;
  ## - unsuitable for publishing a portable Quarto project.
  ##
  ## xfun::relative_path() computes the path of each image relative to the
  ## directory containing the current source document.
  image_relative <- vapply(
    image_absolute,
    xfun::relative_path,
    character(1),
    dir = input_dir
  )
  
  ## ---------------------------------------------------------------------------
  ## 7. Return knitr figure inclusion instructions
  ## ---------------------------------------------------------------------------
  
  ## rel_path = FALSE tells knitr not to perform an additional relative-path
  ## conversion, because the paths have already been calculated explicitly.
  ##
  ## error = FALSE prevents knitr from replacing a missing image with an inline
  ## error graphic. Missing files are already handled above when check_file is
  ## TRUE.
  knitr::include_graphics(
    path = image_relative,
    rel_path = FALSE,
    error = FALSE
  )
}
